// Validates and normalizes the request sent by the Angular app before any quota is consumed.
const UNITS = ['gram', 'kg', 'ml', 'liter', 'piece'];
const COOKING_TIMES = ['quick', 'medium', 'complex'];
const CUISINES = ['german', 'italian', 'indian', 'japanese', 'gourmet', 'fusion'];
const DIETS = ['vegetarian', 'vegan', 'keto', 'none'];
const NAME_PATTERN = /^[\p{L}\p{N} '()\-]{1,60}$/u;
const MAX_INGREDIENTS = 30;

let body = $json.body ?? null;
if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch (error) {
    body = null;
  }
}
const payload = body && typeof body === 'object' && body.data && typeof body.data === 'object' ? body.data : body;
const errors = [];

if (!payload || typeof payload !== 'object') errors.push('The request body must be a JSON object.');

const rawIngredients = Array.isArray(payload?.ingredients) ? payload.ingredients : [];
if (rawIngredients.length < 1) errors.push('At least 1 ingredient is required.');
if (rawIngredients.length > MAX_INGREDIENTS) errors.push(`No more than ${MAX_INGREDIENTS} ingredients are allowed.`);

const merged = new Map();
rawIngredients.slice(0, MAX_INGREDIENTS).forEach((item, index) => {
  const name = String(item?.name ?? '').trim().replace(/\s+/g, ' ');
  const quantity = typeof item?.quantity === 'number' ? item.quantity : NaN;
  const unit = String(item?.unit ?? '').trim().toLowerCase();
  const label = `Ingredient ${index + 1}`;
  let valid = true;

  if (!NAME_PATTERN.test(name)) {
    errors.push(`${label}: the name must be 1-60 letters, numbers, spaces, hyphens, apostrophes or parentheses.`);
    valid = false;
  }
  if (!Number.isFinite(quantity) || quantity <= 0 || quantity > 100000) {
    errors.push(`${label}: the quantity must be a number greater than 0.`);
    valid = false;
  }
  if (!UNITS.includes(unit)) {
    errors.push(`${label}: the unit must be one of ${UNITS.join(', ')}.`);
    valid = false;
  }
  if (!valid) return;

  // Duplicate entries are merged instead of rejected; kg and liter are converted so that
  // "200 g flour" and "1 kg flour" become one ingredient.
  const BASE = { kg: ['gram', 1000], liter: ['ml', 1000] };
  const [baseUnit, factor] = BASE[unit] ?? [unit, 1];
  const key = `${name.toLowerCase()}|${baseUnit}`;
  const existing = merged.get(key);
  if (existing) {
    merged.set(key, { ...existing, quantity: existing.quantity + quantity * factor, unit: baseUnit });
  } else {
    merged.set(key, { name, quantity, unit });
  }
});

const rawPreferences = payload?.preferences;
if (!rawPreferences || typeof rawPreferences !== 'object' || Array.isArray(rawPreferences)) errors.push('The preferences must be a JSON object.');
const preferences = rawPreferences && typeof rawPreferences === 'object' ? rawPreferences : {};
const portions = typeof preferences.portions === 'number' ? preferences.portions : NaN;
const cooks = typeof preferences.cooks === 'number' ? preferences.cooks : NaN;
const cookingTime = String(preferences.cookingTime ?? '').toLowerCase();
const cuisine = String(preferences.cuisine ?? '').toLowerCase();
const diets = Array.isArray(preferences.diets)
  ? [...new Set(preferences.diets.map((diet) => String(diet).toLowerCase()))]
  : [];

if (!Number.isInteger(portions) || portions < 1 || portions > 12) errors.push('Portions must be a whole number between 1 and 12.');
if (!Number.isInteger(cooks) || cooks < 1 || cooks > 3) errors.push('Cooks must be a whole number between 1 and 3.');
if (!COOKING_TIMES.includes(cookingTime)) errors.push(`The cooking time must be one of ${COOKING_TIMES.join(', ')}.`);
if (!CUISINES.includes(cuisine)) errors.push(`The cuisine must be one of ${CUISINES.join(', ')}.`);
if (!diets.length || diets.some((diet) => !DIETS.includes(diet))) errors.push(`Diets must contain one or more of ${DIETS.join(', ')}.`);
if (diets.includes('none') && diets.length > 1) errors.push('"none" cannot be combined with other diets.');

return [{
  json: {
    ...$json,
    requestValid: errors.length === 0,
    validationErrors: errors,
    validationMessage: errors.length ? `Invalid request: ${errors[0]}` : null,
    request: {
      ingredients: [...merged.values()],
      preferences: { portions, cooks, cookingTime, cuisine, diets },
    },
  },
}];

// Enforces the per-IP daily quota, the global daily quota and a short throttle between requests of one IP.
// Firebase only accepts "+1" writes on these counters (database.rules.json), so nobody can reset them,
// and a write that loses a race against a parallel request is rejected instead of passing twice.
const PER_IP_LIMIT = 3;
const GLOBAL_LIMIT = 12;
const THROTTLE_MS = 15000;
// Your own Firebase Realtime Database URL (same value as firebaseDatabaseUrl in the Angular environment).
const dbUrl = 'https://code-a-cuisine-7b803-default-rtdb.europe-west1.firebasedatabase.app';
// Code nodes on n8n Cloud have no global fetch, so Firebase is reached through n8n's HTTP helper.
const httpRequest = this.helpers.httpRequest.bind(this.helpers);

const IPV4 = /^(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)(\.(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)){3}$/;

// Expands an IPv6 address to 8 groups of 4 hex digits, or returns null when it is not valid.
// IPv4-mapped addresses (::ffff:1.2.3.4) are handled as the IPv4 address they carry.
const expandIpv6 = (value) => {
  let text = value.toLowerCase().replace(/^\[|\]$/g, '').split('%')[0];
  const embedded = text.match(/^(.*:)(\d+\.\d+\.\d+\.\d+)$/);
  if (embedded) {
    if (!IPV4.test(embedded[2])) return null;
    const [a, b, c, d] = embedded[2].split('.').map(Number);
    text = `${embedded[1]}${((a << 8) | b).toString(16)}:${((c << 8) | d).toString(16)}`;
  }
  if (!/^[0-9a-f:]+$/.test(text) || text.split('::').length > 2) return null;
  const [head, tail] = text.includes('::') ? text.split('::') : [text, null];
  const headGroups = head ? head.split(':') : [];
  const tailGroups = tail ? tail.split(':') : [];
  const missing = 8 - headGroups.length - tailGroups.length;
  if (tail === null ? missing !== 0 : missing < 1) return null;
  const groups = [...headGroups, ...Array(tail === null ? 0 : missing).fill('0'), ...tailGroups];
  if (groups.length !== 8 || groups.some((group) => !/^[0-9a-f]{1,4}$/.test(group))) return null;
  return groups.map((group) => group.padStart(4, '0'));
};

// Returns the address in canonical form plus the key the quota is counted under.
// IPv6 is counted per /64 network: one connection usually owns a whole /64.
const parseIp = (raw) => {
  const value = String(raw ?? '').trim();
  if (IPV4.test(value)) return { ip: value, version: 'ipv4', quotaKey: value };
  const groups = expandIpv6(value);
  if (!groups) return null;
  if (groups.slice(0, 5).every((group) => group === '0000') && groups[5] === 'ffff') {
    const n = parseInt(groups[6] + groups[7], 16);
    const ipv4 = [n >>> 24, (n >>> 16) & 255, (n >>> 8) & 255, n & 255].join('.');
    return { ip: ipv4, version: 'ipv4', quotaKey: ipv4 };
  }
  return { ip: groups.join(':'), version: 'ipv6', quotaKey: `${groups.slice(0, 4).join(':')}::/64` };
};

// n8n Cloud sits behind Cloudflare: cf-connecting-ip is set by Cloudflare itself and cannot be
// sent by the browser; x-real-ip is the fallback set by the n8n proxy. x-forwarded-for is not used,
// its last entry is a Cloudflare address and the first one can be forged by the client.
const headers = $json.headers ?? {};
const candidates = [headers['cf-connecting-ip'], headers['x-real-ip']];
const parsed = candidates.map(parseIp).find(Boolean) ?? null;
const ip = parsed?.ip ?? 'unknown';
const ipVersion = parsed?.version ?? 'unknown';

// The database never sees the address itself, only a SHA-256 hash of the quota key.
let ipKey = 'unknown';
if (parsed) {
  try {
    ipKey = require('crypto').createHash('sha256').update(`code-a-cuisine:${parsed.quotaKey}`).digest('hex').slice(0, 32);
  } catch (error) {
    ipKey = parsed.quotaKey.replace(/[^a-zA-Z0-9]/g, '-');
  }
}

const now = Date.now();
const today = new Date(now).toLocaleDateString('sv-SE', { timeZone: 'Europe/Berlin' });
const perIpPath = `${dbUrl}/quota/${today}/ips/${ipKey}.json`;
const globalPath = `${dbUrl}/quota/${today}/global.json`;

const readJson = async (url) => {
  try {
    return { ok: true, data: await httpRequest({ method: 'GET', url, json: true }) };
  } catch (error) {
    return { ok: false, data: null, error: error.message };
  }
};
const writeJson = (url, value) => httpRequest({
  method: 'PUT',
  url,
  body: JSON.stringify(value),
  headers: { 'Content-Type': 'application/json' },
});

const buildQuota = (ipUsed, globalCount) => ({
  date: today,
  ipAddress: ip,
  ipVersion,
  perIpLimit: PER_IP_LIMIT,
  perIpUsed: ipUsed,
  perIpRemaining: Math.max(0, PER_IP_LIMIT - ipUsed),
  globalLimit: GLOBAL_LIMIT,
  globalUsed: globalCount,
  globalRemaining: Math.max(0, GLOBAL_LIMIT - globalCount),
});

// Reads both counters and decides; returns the decision plus the values to write.
const evaluate = async () => {
  const [ipResult, globalResult] = await Promise.all([readJson(perIpPath), readJson(globalPath)]);
  if (!ipResult.ok || !globalResult.ok) {
    return { ok: false, code: 'QUOTA_UNAVAILABLE', message: 'The usage limit could not be checked right now. Please try again in a moment.', perIpUsed: 0, globalUsed: 0 };
  }
  const remoteIp = ipResult.data && typeof ipResult.data === 'object' ? ipResult.data : {};
  const perIpUsed = Number(remoteIp.count) || 0;
  const lastRequestAt = Number(remoteIp.lastRequestAt) || 0;
  const globalUsed = Number(globalResult.data) || 0;
  const waitSeconds = Math.ceil((THROTTLE_MS - (now - lastRequestAt)) / 1000);

  if (ipVersion === 'unknown') {
    return { ok: false, code: 'IP_NOT_DETECTED', message: 'Your IP address could not be detected, so no quota can be assigned. Please try again later.', perIpUsed, globalUsed };
  }
  if (perIpUsed >= PER_IP_LIMIT) {
    return { ok: false, code: 'QUOTA_EXCEEDED', message: `Daily limit reached: ${PER_IP_LIMIT} recipe generations per IP address per day. Please come back tomorrow.`, perIpUsed, globalUsed };
  }
  if (globalUsed >= GLOBAL_LIMIT) {
    return { ok: false, code: 'GLOBAL_QUOTA_EXCEEDED', message: `The app has reached its daily limit of ${GLOBAL_LIMIT} recipe generations. Please come back tomorrow.`, perIpUsed, globalUsed };
  }
  if (now - lastRequestAt < THROTTLE_MS) {
    return { ok: false, code: 'THROTTLED', message: `Too many requests. Please wait ${waitSeconds} seconds before generating again.`, perIpUsed, globalUsed };
  }
  return { ok: true, code: null, message: null, perIpUsed, globalUsed };
};

// Books one generation. Firebase rejects a write whose count is not exactly the stored value + 1,
// so when a parallel request was faster the counters are read again once before giving up.
let decision = await evaluate();
let booked = false;
for (let attempt = 1; decision.ok && !booked && attempt <= 2; attempt += 1) {
  try {
    await writeJson(globalPath, decision.globalUsed + 1);
    await writeJson(perIpPath, { count: decision.perIpUsed + 1, lastRequestAt: now, ipVersion });
    booked = true;
  } catch (error) {
    console.log(`Quota booking attempt ${attempt} was rejected: ${error.message}`);
    decision = await evaluate();
  }
}
if (decision.ok && !booked) {
  decision = { ...decision, ok: false, code: 'THROTTLED', message: 'Too many requests at the same time. Please try again in a few seconds.' };
}

const quota = booked
  ? buildQuota(decision.perIpUsed + 1, decision.globalUsed + 1)
  : buildQuota(decision.perIpUsed, decision.globalUsed);
if (!decision.ok) {
  console.log(`Quota rejected (${decision.code}) for ${ipVersion} key ${ipKey}`);
}

return [{
  json: {
    ...$json,
    ipAddress: ip,
    ipVersion,
    ipKey,
    quotaDate: today,
    quotaOk: decision.ok,
    quotaErrorCode: decision.code,
    quotaExceededMessage: decision.message,
    quota,
  },
}];

// Builds the recipe prompt and the JSON schema for the Structured Output Parser from the validated
// request. The recipe rules live in the schema, so the parser checks them and lets the model fix
// a broken answer (auto-fix) instead of a hand-written validation loop.
const { request } = $json;
const { ingredients, preferences } = request;

const COOKING_TIMES = {
  quick: { text: 'quick, at most 20 minutes in total', min: 5, max: 20 },
  medium: { text: 'medium, between 20 and 45 minutes in total', min: 20, max: 45 },
  complex: { text: 'elaborate, more than 45 minutes in total', min: 46, max: 300 },
};
const CUISINES = {
  german: 'German cuisine',
  italian: 'Italian cuisine',
  indian: 'Indian cuisine',
  japanese: 'Japanese cuisine',
  gourmet: 'Gourmet / fine dining',
  fusion: 'Fusion, an international mix of styles',
};
const DIET_RULES = {
  vegetarian: 'Vegetarian: no meat, poultry, fish, seafood or gelatine.',
  vegan: 'Vegan: no animal products at all (no meat, fish, dairy, eggs, honey or gelatine).',
  keto: 'Keto: at most 20 g net carbohydrates per portion; no sugar, flour, rice, pasta, potatoes or bread.',
  none: 'No dietary restrictions.',
};
const UNIT_LABELS = { gram: 'g', kg: 'kg', ml: 'ml', liter: 'l', piece: 'piece(s)' };

const names = [...new Set(ingredients.map((item) => item.name))];
const minUsed = Math.ceil(names.length * 0.7);
const time = COOKING_TIMES[preferences.cookingTime];
const ingredientList = ingredients
  .map((item) => `- ${item.name}: ${item.quantity} ${UNIT_LABELS[item.unit] ?? item.unit} available`)
  .join('\n');
const dietRules = preferences.diets.map((diet) => `  - ${DIET_RULES[diet]}`).join('\n');
const cooksRule = preferences.cooks > 1
  ? `Split the work between the ${preferences.cooks} cooks so that every cook has their own tasks. Steps that different cooks do at the same time get "parallel": true.`
  : 'There is only one cook: set "cook" to 1 and "parallel" to false for every step.';

const prompt = `Create exactly 3 recipes from the ingredients a home cook already has.

Available ingredients:
${ingredientList}

Preferences:
- Portions: ${preferences.portions}
- People cooking together: ${preferences.cooks}
- Time frame: ${time.text}
- Cuisine: ${CUISINES[preferences.cuisine]}
- Diet:
${dietRules}

Rules:
1. The 3 recipes must have different titles and clearly differ in cooking method (for example pan, oven, raw, soup) or flavour profile.
2. Each recipe uses at least ${minUsed} of the ${names.length} available ingredients; list the ones it uses in "usedIngredients", spelled exactly as above. Leave out an available ingredient only if it breaks the diet rules.
3. Each recipe may add at most 3 extra basic ingredients (for example salt, pepper, oil, water or a common spice). List them in "extraIngredients" and also in "ingredients".
4. Scale all quantities in "ingredients" for exactly ${preferences.portions} portion(s) and never use more than the available amount. Format: "<quantity> <unit> <name>", for example "200 g pasta".
5. "estimatedMinutes" is between ${time.min} and ${time.max}.
6. Use spices, techniques and dishes that are typical for the cuisine.
7. Steps are chronological, easy to follow for beginners and 4 to 12 per recipe. Every step has a short "title" (2-6 words), a clear "instruction", "cook" (1 to ${preferences.cooks}) and "durationMinutes".
8. ${cooksRule}
9. Use waiting times (boiling, baking, resting) for other preparations and say so in the instruction.
10. "nutrition" contains realistic estimates in kcal and grams: "perPortion" for one portion and "total" for the whole recipe, which is perPortion times ${preferences.portions}.`;

// JSON schema of the answer. The limits come from the request, so the parser enforces them per call.
const macros = (maxCarbs) => ({
  type: 'object',
  properties: {
    calories: { type: 'number', minimum: 0 },
    protein: { type: 'number', minimum: 0 },
    carbs: maxCarbs ? { type: 'number', minimum: 0, maximum: maxCarbs } : { type: 'number', minimum: 0 },
    fat: { type: 'number', minimum: 0 },
  },
  required: ['calories', 'protein', 'carbs', 'fat'],
});
const recipeSchema = {
  type: 'object',
  properties: {
    recipes: {
      type: 'array',
      minItems: 3,
      maxItems: 3,
      items: {
        type: 'object',
        properties: {
          title: { type: 'string', minLength: 3 },
          description: { type: 'string' },
          estimatedMinutes: { type: 'integer', minimum: time.min, maximum: time.max },
          usedIngredients: { type: 'array', items: { type: 'string', enum: names }, minItems: minUsed, uniqueItems: true },
          ingredients: { type: 'array', items: { type: 'string' }, minItems: minUsed },
          extraIngredients: { type: 'array', items: { type: 'string' }, maxItems: 3 },
          steps: {
            type: 'array',
            minItems: 4,
            maxItems: 12,
            items: {
              type: 'object',
              properties: {
                title: { type: 'string' },
                instruction: { type: 'string' },
                cook: { type: 'integer', minimum: 1, maximum: preferences.cooks },
                parallel: { type: 'boolean' },
                durationMinutes: { type: 'number', minimum: 0 },
              },
              required: ['title', 'instruction', 'cook', 'parallel', 'durationMinutes'],
            },
          },
          nutrition: {
            type: 'object',
            properties: {
              perPortion: macros(preferences.diets.includes('keto') ? 20 : null),
              total: macros(null),
            },
            required: ['perPortion', 'total'],
          },
        },
        required: ['title', 'description', 'estimatedMinutes', 'usedIngredients', 'ingredients', 'extraIngredients', 'steps', 'nutrition'],
      },
    },
  },
  required: ['recipes'],
};

return [{ json: { ...$json, prompt, recipeSchema: JSON.stringify(recipeSchema), ingredientCount: names.length } }];

// Logs a failed recipe generation or a crashed node to the execution log and to Firebase, then
// passes a fixed, user-friendly message on to the error response. Technical details stay in the log.
const dbUrl = 'https://code-a-cuisine-7b803-default-rtdb.europe-west1.firebasedatabase.app';
const USER_MESSAGE = 'The recipes could not be created this time. Please try again.';

let ipVersion = 'unknown';
try {
  ipVersion = $('Check IP Quota').first().json.ipVersion ?? 'unknown';
} catch (error) {
  // Check IP Quota itself failed, so there is no IP information.
}

const entry = {
  at: new Date().toISOString(),
  workflow: $workflow.name,
  executionId: $execution.id,
  message: String($json.recipeErrorMessage ?? $json.error?.message ?? $json.error ?? 'Recipe generation failed').slice(0, 2000),
  issues: $json.recipeIssues ?? [],
  ipVersion,
};

console.log(`Recipe generation failed: ${entry.message} ${entry.issues.join(' ')}`);
try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${dbUrl}/logs/recipeErrors.json`,
    body: JSON.stringify(entry),
    headers: { 'Content-Type': 'application/json' },
  });
} catch (error) {
  console.log(`Writing the error log failed: ${error.message}`);
}

return [{ json: { ...$json, recipeErrorMessage: USER_MESSAGE } }];

// The Structured Output Parser has already checked every rule of the schema, so this node only
// prepares the answer for the app: step texts, per-cook step details and the ingredient coverage.
const { request, ingredientCount, quota, ipAddress } = $('Prepare Prompt').first().json;
const { preferences } = request;

const recipes = $json.output.recipes.map((recipe) => {
  const stepDetails = recipe.steps.map((step) => ({ ...step, parallel: preferences.cooks > 1 && step.parallel }));
  return {
    ...recipe,
    steps: stepDetails.map((step) => `${step.title}: ${step.instruction}`),
    stepDetails,
    ingredientCoverage: Math.round((recipe.usedIngredients.length / ingredientCount) * 100),
  };
});

return [{ json: { ...request, ipAddress, quota, recipeResult: { recipes } } }];
